    title: "البريد الجامعي",
    content: `البريد الجامعي هو وسيلة التواصل الرسمية بين الطالبة والجامعة، ويلزم تفعيله وتسجيل الدخول إليه بانتظام لمتابعة كل ما يخص مسيرتك الجامعية (الإشعارات، المواعيد، والرسائل الرسمية).

تنبيه مهم: إهمال البريد الجامعي وعدم فتحه لمدة 3 أشهر يؤدي إلى إغلاقه، وتتحمل الطالبة مسؤولية ما يصلها من مراسلات مهمة عليه.

عند وجود أي مشكلة في بريدك الجامعي، تواصلي مع: itc-sd@pnu.edu.sa

من فوائد البريد الجامعي أيضًا: الوصول لخدمات وبرامج مجانية عبره، مثل برامج مايكروسوفت أوفيس، والوصول إلى قواعد البيانات في المكتبة الرقمية السعودية (روابط توضيحية ومنشورات عن فوائد إضافية بالأسفل ضمن الروابط).`,
