    slug: "smart-bag",
    title: "الحقيبة الذكية",
    content: `ما هي الحقيبة الذكية؟
هي إحدى الخدمات السحابية التي تقدمها جامعة الأميرة نورة بنت عبدالرحمن بالشراكة مع شركة مايكروسوفت العالمية، وتمكّن الطالبات ومنسوبي الجامعة من التواصل ومشاركة المعلومات والبيانات بكل يسر وسهولة.

خدمات الحقيبة الذكية:

خدمة البريد الإلكتروني (Microsoft Outlook):
يعتبر البريد الإلكتروني الجامعي عنوان الطالبة ووسيلة التواصل الرسمية خلال المرحلة الجامعية، ويُستخدم في التواصل مع أعضاء هيئة التدريس، ومعرفة الأنشطة اللامنهجية، والإعلانات الجامعية.

خدمة مايكروسوفت تيمز (Microsoft Teams):
تساهم هذه الخدمة في إنشاء حلقات اتصال افتراضية أو مجموعات رسمية لعقد الاجتماعات والدروس، وهي وسيلة تواصل مع أعضاء هيئة التدريس وزميلات الدراسة عبر المكالمات الصوتية والمرئية والرسائل النصية.

خدمة الأوفيس عبر الإنترنت (Microsoft Office Online):
تمكّن الطالبات من استخدام حزمة مايكروسوفت أوفيس دون الحاجة لتثبيت البرامج، من خلال المتصفح مباشرة، مع إمكانية العمل الجماعي على نفس الملف وحفظه عبر التخزين السحابي (OneDrive).

خدمة شبكة التواصل الاجتماعي يامِر (Yammer):
شبكة تواصل تمكّن المجموعات ذات المنفعة المشتركة من متابعة بعضهن البعض بما يخص أمور العمل.

خدمة التخزين السحابية (OneDrive):
تمكّن الطالبات من رفع ومزامنة الملفات إلى سحابة تخزين يسهل الوصول إليها، وتقدم الجامعة سعة تخزين سحابية تبلغ 1 تيرابايت.

خدمة الأوفيس برو بلس (Office Pro Plus):
تمكّن الطالبات وأعضاء هيئة التدريس من التحميل والتنشيط المجاني لحزمة Microsoft Office على أجهزتهن الشخصية، وتشمل: Word، Excel، PowerPoint، Sway، وOneNote.

كيفية الدخول إلى الحقيبة الذكية:
اسم المستخدم: رقمك الجامعي متبوعًا بـ @pnu.edu.sa
كلمة السر: رقم هويتك الوطنية متبوعًا بـ @pnu (مثال: إذا كان رقم هويتك 1111111111 فكلمة السر تكون 1111111111@pnu)

طريقة استخدام الحقيبة الذكية:
وفّرت الجامعة كتيبًا إلكترونيًا شاملًا يوضح آلية الاستفادة من هذي الخدمات (رابط الكتيب بالأسفل ضمن الروابط).`,
