    slug: "study-plan",
    title: "الخطة الدراسية",
    sections: [
      {
        title: "الخطة الدراسية",
        content: `لكل تخصص خطة دراسية خاصّة به؛ تُمكّن الطالبة من معرفة جميع المقررات المطلوبة لدراسة التخصص، وآلية توزيعها على المستويات، وعدد الساعات اللازمة لإتمام التخصص خلال فترة زمنية محددة.

أقسام المقررات الجامعية:

متطلبات الجامعة:
مقررات مشتركة بين جميع التخصصات بمختلف الكليات داخل الجامعة، وتنقسم إلى قسمين:
- المقررات الإجبارية: مقررات اللغة الإنجليزية، ومقررات من مجال تعزيز القيم الإسلامية.
- المقررات الاختيارية: مقررات عامة غير محددة؛ للطالبة حرية اختيار أي مجال من المجالات الاختيارية (يُستثنى من ذلك مجال المهارات التقنية ومعالجة البيانات، ومقرر مبادئ المشاريع؛ لأنهما محجوبان من برامج كلية علوم الحاسب والمعلومات)، وبحد أقصى مقرر واحد من كل مجال، بحيث تُتم الطالبة أربعة مقررات بالإضافة إلى المقررين الإجباريين من مجال تعزيز القيم الإسلامية، كما هو موضح في خطتها الدراسية.

متطلبات الكلية:
مقررات مشتركة بين جميع تخصصات الكلية.
- الإجبارية: مقررات مشتركة بين جميع تخصصات الكلية الواحدة.
- الاختيارية: لا يوجد متطلبات كلية اختيارية في كلية علوم الحاسب والمعلومات.

متطلبات البرنامج:
- الإجبارية: مقررات تابعة للتخصص ذاته، تُزوّد الطالبة بالمهارات والمعرفة اللازمة لممارسة تخصصها عمليًا.
- الاختيارية: مجموعة مقررات معنيّة بمواضيع التخصص، يمكن للطالبة اختيار عدد منها بما يتوافق مع ساعات خطتها الدراسية للمقررات الاختيارية.

المدة النظامية:
هي الحد الأقصى لمدة بقاء الطالبة في الجامعة لإنهاء متطلبات التخرج (جميع المقررات المطلوب إنهاؤها قبل التخرج).
تُحتسب المدة النظامية بإضافة مدة البرنامج إلى نصف المدة؛ فعلى سبيل المثال: مدة برامج كلية علوم الحاسب والمعلومات حسب خطة الفصلين هي 8 فصول، وبالتالي تكون المدة النظامية 12 فصلًا.
- تُحتسب ضمن المدة النظامية: فصول الاعتذار، وفصول التحويل، والفصل التأديبي.
- لا تُحتسب: فصول التأجيل، وفصول الانقطاع.`,
      },
      {
        title: "المعدّل",
        content: `يُعدّ المعدّل مؤشرًا أكاديميًا لأداء الطالبة خلال مسيرتها الدراسية. وتطبق جامعة الأميرة نورة نظام المعدّل من (5). يعتمد هذا النظام على تحويل الدرجة التي تحصل عليها الطالبة في كل مقرر إلى تقدير معيَّن بناءً على الدرجة المستحقة لها، ويتم احتساب المعدّل بقسمة مجموع النقاط في جميع المقررات على مجموع الساعات المعتمدة لتلك المقررات.

أنواع المعدّلات:
- المعدّل الفصلي: هو المعدّل الذي يُحتسب لمقررات فصل دراسي واحد فقط، دون النظر للفصول الأخرى.
- المعدّل التراكمي (GPA): هو المعدّل المعتمد في وثيقة التخرج، ويشمل متوسط تقديرات جميع المقررات التي درستها الطالبة، سواء نجحت فيها أو رسبت، في جميع الفصول الدراسية.

جدول التقديرات ونسبها موضح بالأسفل ضمن الجداول.

ساعات المعدّل:
تنقسم الساعات المستخدمة في حساب المعدّل إلى:
- الساعات المسجَّلة: عدد الساعات التي سجلتها الطالبة في الفصل أو في جميع الفصول الدراسية.
- الساعات المجتازة: عدد الساعات التي أنهتها الطالبة بنجاح من بين الساعات المسجَّلة.
- الساعات المكتسَبة: عدد الساعات المعتمدة التي اجتازتها الطالبة أو تم معادلتها، ولا تشمل المواد المتعثرة.

احتساب المعدل:
- مجموع نقاط المقرر = عدد ساعات المقرر × عدد نقاط التقدير (من 5).
- المعدل الفصلي = مجموع نقاط مقررات الفصل ÷ مجموع الساعات.
- المعدل التراكمي = مجموع نقاط جميع الفصول ÷ مجموع الوحدات الدراسيّة.

بعض التطبيقات المستخدمة في حساب المعدل الفصلي والتراكمي: GPA Smile، احسب معدلي، احسب معدلك.

المنصّات المستخدمة للاستعلام عن المعدل الفصلي والتراكمي: النظام الأكاديمي - البانر (Banner)، وتطبيق أو موقع "طالبات نورة".

آلية حساب الغياب والحرمان:
- يجب على الطالبة حضور المحاضرات والدروس بانتظام.
- يُحدد لكل مقرر نسبة غياب مسموح بها، وإذا تجاوزتها الطالبة، تُمنع من دخول الاختبار النهائي (جدول تفصيلي بالساعات موضح بالأسفل ضمن الجداول).
- تقوم أستاذة المقرر بإعلان أسماء الطالبات اللواتي بلغن النسبة المحددة للحرمان.
- في حال تجاوزت الطالبة نسبة الغياب 25% من الساعات المقررة، تُحرَم من دخول الاختبار ويُرصد لها تقدير "محروم" (ح) أو (DN).
- تُعتبر الطالبة التي تُحرم من دخول الاختبار بسبب تجاوزها نسبة الغياب راسبة في المقرر.
- يمكن لمجلس الكلية النظر في رفع الحرمان في حالات الأعذار المقبولة.
- إذا قلّت نسبة حضور الطالبة عن 50% من ساعات المقرر، لا يُسمح لها بدخول الاختبار النهائي.
- يُطوى قيد الطالبة التي تغيبت عن الدراسة (في جميع المقررات) دون عذر مقبول.`,
      },
    ],
