        content: `السجل المهاري هو وثيقة رسمية معتمدة من الجامعة تُصدر للطالبة عند التخرج، وتوثّق كافة المهارات الحياتية والشخصية والمهنية غير الأكاديمية التي اكتسبتها الطالبة خلال فترة دراستها الجامعية، سواء من أنشطة ودورات داخل الجامعة أو من جهات خارجية معتمدة.`,
