        content: `1. أن تكون الطالبة منتظمة في جامعة الأميرة نورة بنت عبدالرحمن.
2. أن تكون الشهادة التي حصلت عليها الطالبة خلال فترة الدراسة معتمدة ومختومة من قِبَل الجهة المنظمة للنشاط، ويتعين على الجامعة التحقق من صحتها.
3. يُشترط أن تحصل الطالبة على جميع المهارات المطلوبة؛ سواءً من جهات داخل الجامعة أو من جهات معتمدة خارجها.
4. لا يتم اعتماد البيانات إلا بعد مراجعة منسقة النشاط في الكلية لمطابقة الشهادات.
5. لا يمكن التعديل أو الإضافة في السجل بعد اعتماده إلا بمراجعة عمادة شؤون الطالبات.`,
